        if south > float(gp['south_cap_kw']) + 1e-9: viol.append(('south_cap', mid, south, float(gp['south_cap_kw'])))
        if site > float(gp['site_cap_kw']) + 1e-9: viol.append(('site_cap', mid, site, float(gp['site_cap_kw'])))
