    detail=[]
    for bid,b in bus_by.items():
        # simulate schedule and check if bus can be at depot idle at time t given events and deadhead feasibility.
        events=sorted(bus_events.get(bid,[]), key=lambda e:(e['start'],e['end'],e['id']))
        soc=float(b['initial_soc_kwh'])
        loc='DEPOT'
        time=0
        feasible=False
        # if no events
        if not events:
            feasible = soc >= soc_req
        else:
            for i,ev in enumerate(events):
                # can bus be at depot idle at t before this event?
                # from current loc at current time, can reach depot by t and then next ev by start?
                if t < ev['start']:
                    to_depot = dead_by[(loc,'DEPOT')]
                    depot_to_next = dead_by[('DEPOT',ev['from'])]
                    earliest_depot=time+to_depot
                    latest_leave=ev['start']-depot_to_next
                    if earliest_depot <= t <= latest_leave and soc >= soc_req:
                        feasible=True
                        break
                # if checkpoint during trip/charge not idle
                if ev['kind']=='trip' and ev['start'] <= t < ev['end']:
                    feasible=False
                    break
                if ev['kind']=='charge' and ev['start'] <= t < ev['end']:
                    feasible=False
                    break
                # advance through event
                travel=dead_by[(loc,ev['from'])]
                time=max(time+travel, ev['start'])
                if ev['kind']=='trip':
                    soc -= ev['energy']*trip_multiplier(bid, ev['start'], ev['end'])
                else:
                    soc += ev['energy']
                time=ev['end']
                loc=ev['to']
            else:
                # after last event
                to_depot=dead_by[(loc,'DEPOT')]
                if time+to_depot <= t and soc >= soc_req:
                    feasible=True
        if feasible:
            cnt += 1
            detail.append((bid, round(soc,1)))
    if cnt < int(rr['min_buses']):
        viol.append(('reserve_checkpoint', t, cnt, int(rr['min_buses'])))
    print('RESERVE', t, 'count', cnt, 'need', rr['min_buses'], 'sample', detail[:8])

# objective partials
cancel_pen=sum(float(trip_by[r['trip_id']]['cancel_penalty']) for r in trip_rows if r['decision']=='cancel' and r['trip_id'] in trip_by)
charge_energy=sum(float(r['energy_kwh']) for r in charge_rows)

print('rows', len(plan), 'trip_rows', len(trip_rows), 'charge_rows', len(charge_rows))
print('unused_buses', unused)
print('violations', len(viol))
for v in viol[:50]:
    print('VIOL', v)

# tight SOC margins
for bid,events in sorted(bus_events.items()):
    soc=float(bus_by[bid]['initial_soc_kwh'])
    min_soc=float(bus_by[bid]['min_soc_kwh'])
    min_margin=1e9
    min_event=None
    for ev in sorted(events,key=lambda e:e['start']):
        if ev['kind']=='trip':
            start_margin=soc-ev['min_start_soc']
            if start_margin<min_margin:
                min_margin=start_margin; min_event=(ev['id'],'start',start_margin)
            soc -= ev['energy']*trip_multiplier(bid, ev['start'], ev['end'])
            end_margin=soc-min_soc
            if end_margin<min_margin:
                min_margin=end_margin; min_event=(ev['id'],'end',end_margin)
        else:
            soc += ev['energy']
    print('SOC_MARGIN', bid, min_event, 'final_soc', round(soc,1))

# time margins
for bid,events in sorted(bus_events.items()):
    prev_end=0; prev_loc='DEPOT'; tight=None
    for ev in sorted(events,key=lambda e:e['start']):
        ready=prev_end+dead_by[(prev_loc, ev['from'])]
        slack=ev['start']-ready
        if tight is None or slack < tight[1]:
            tight=(ev['id'], slack, ready, ev['start'], prev_loc, ev['from'])
        prev_end=ev['end']; prev_loc=ev['to']
    print('TIME_MARGIN', bid, tight)

print('CANCEL_PEN', cancel_pen)
print('CHARGE_ENERGY', charge_energy)
