boundaries=sorted({0,1440,*[int(float(r['start_min'])) for r in charge_rows],*[int(float(r['end_min'])) for r in charge_rows],*[int(g['start_min']) for g in grid],*[int(g['end_min']) for g in grid]})

def active_power(r, t):
    s,e=int(float(r['start_min'])),int(float(r['end_min']))
    if not (s<=t<e):
        return 0.0
    dur=e-s
    return float(r['energy_kwh'])*60.0/dur if dur>0 else 0.0

for t0,t1 in zip(boundaries,boundaries[1:]):
    if t0==t1: continue
    mid=t0
    north=south=site=fast_north=fast_south=fast_site=0.0
    new_sessions_all=0
    for r in charge_rows:
        p=active_power(r, mid)
        if p>0:
            ch=charger_by[r['charger_id']]
            if ch['feeder']=='north': north += p
            else: south += p
            site += p
            if ch['charger_type']=='fast':
                if ch['feeder']=='north': fast_north += 1
                else: fast_south += 1
                fast_site += 1
        if int(float(r['start_min']))==mid:
            new_sessions_all += 1
    gp=next((g for g in grid if int(g['start_min'])<=mid<int(g['end_min'])),None)
    if gp:
        if north > float(gp['north_cap_kw']) + 1e-9: viol.append(('north_cap', mid, north, float(gp['north_cap_kw'])))
        if south > float(gp['south_cap_kw']) + 1e-9: viol.append(('south_cap', mid, south, float(gp['south_cap_kw'])))
        if site > float(gp['site_cap_kw']) + 1e-9: viol.append(('site_cap', mid, site, float(gp['site_cap_kw'])))
    for lim in session_limits:
