        if new_sessions_all > int(lim['max_new_sessions']):
            viol.append(('max_new_sessions', mid, new_sessions_all, int(lim['max_new_sessions'])))
        mf=int(lim['max_fast_active'])
        scope=lim['scope']
        if scope=='all' and fast_site > mf:
            viol.append(('max_fast_active', mid, fast_site, mf))
        if scope=='north' and fast_north > mf:
            viol.append(('max_fast_active_north', mid, fast_north, mf))
        if scope=='south' and fast_south > mf:
            viol.append(('max_fast_active_south', mid, fast_south, mf))

# reserves: existence of idle-at-depot buses at checkpoint under the implied schedule where buses can wait/deadhead within slack
# Conservative sufficient count: buses with no assigned events are at depot all day.
unused=[b for b in bus_by if b not in bus_events]
for rr in reserves:
    t=int(rr['checkpoint_min'])
    soc_req=float(rr['min_soc_kwh'])
    cnt=0
    detail=[]
    for bid,b in bus_by.items():
        # simulate schedule and check if bus can be at depot idle at time t given events and deadhead feasibility.
        events=sorted(bus_events.get(bid,[]), key=lambda e:(e['start'],e['end'],e['id']))
        soc=float(b['initial_soc_kwh'])
        loc='DEPOT'
        time=0
        feasible=False
        # if no events
        if not events:
            feasible = soc >= soc_req
        else:
            for i,ev in enumerate(events):
                # can bus be at depot idle at t before this event?
                # from current loc at current time, can reach depot by t and then next ev by start?
                if t < ev['start']:
                    to_depot = dead_by[(loc,'DEPOT')]
                    depot_to_next = dead_by[('DEPOT',ev['from'])]
                    earliest_depot=time+to_depot
                    latest_leave=ev['start']-depot_to_next
                    if earliest_depot <= t <= latest_leave and soc >= soc_req:
                        feasible=True
                        break
                # if checkpoint during trip/charge not idle
                if ev['kind']=='trip' and ev['start'] <= t < ev['end']:
                    feasible=False
                    break
                if ev['kind']=='charge' and ev['start'] <= t < ev['end']:
                    feasible=False
                    break
                # advance through event
                travel=dead_by[(loc,ev['from'])]
                time=max(time+travel, ev['start'])
                if ev['kind']=='trip':
                    soc -= ev['energy']*trip_multiplier(bid, ev['start'], ev['end'])
                else:
                    soc += ev['energy']
                time=ev['end']
                loc=ev['to']
            else:
                # after last event
                to_depot=dead_by[(loc,'DEPOT')]
                if time+to_depot <= t and soc >= soc_req:
                    feasible=True
        if feasible:
            cnt += 1
            detail.append((bid, round(soc,1)))
    if cnt < int(rr['min_buses']):
        viol.append(('reserve_checkpoint', t, cnt, int(rr['min_buses'])))
    print('RESERVE', t, 'count', cnt, 'need', rr['min_buses'], 'sample', detail[:8])

